import csv
import io

_DIGITS = frozenset('0123456789')


def _row_field(row, column):
    try:
        value = row[column]
    except KeyError:
        raise ValueError('missing %r column' % column)
    if value is None:
        raise ValueError('missing %r field' % column)
    return value


def import_text(text, store, dry_run=False):
    rows = list(csv.DictReader(io.StringIO(text)))

    # Validate every row before committing any changes.
    items = []
    for row in rows:
        sku = _row_field(row, 'sku').strip()
        name = _row_field(row, 'name').strip()
        qty_text = _row_field(row, 'qty').strip()
        if not sku:
            raise ValueError('sku must not be empty')
        if not name:
            raise ValueError('name must not be empty')
        if not qty_text or not all(ch in _DIGITS for ch in qty_text):
            raise ValueError('qty must contain only decimal digits')
        items.append({'sku': sku, 'name': name, 'qty': int(qty_text)})

    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}
    for item in items:
        before = store.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item})
        if not dry_run:
            store.put(item)
    return result

